-- ── 4. ASSIGN master_product_id, master_sku, category_id, subcategory_id TO EXISTING 50 PRODUCTS ──
-- Map by created_at order (DET-001 through DET-050 are all Rings per master catalog)
-- We use a numbered approach based on the master catalog ordering

DO $$
DECLARE
  rec RECORD;
  counter INTEGER := 1;
  pid TEXT;
  psku TEXT;
  cat_id UUID;
  sub_id UUID;
BEGIN
  FOR rec IN
    SELECT id, category, slug, name
    FROM public.products
    WHERE master_product_id IS NULL
    ORDER BY created_at ASC, id ASC
    LIMIT 50
  LOOP
    pid  := 'DET-' || LPAD(counter::text, 3, '0');
    psku := 'DET-R-' || LPAD(counter::text, 3, '0');
    cat_id := '11111111-0001-0001-0001-000000000001'::uuid; -- Rings

    -- Assign subcategory based on counter ranges matching master catalog
    sub_id := CASE
      WHEN counter BETWEEN 1  AND 15 THEN '22222222-0001-0001-0001-000000000001'::uuid  -- Solitaire Rings
      WHEN counter BETWEEN 16 AND 25 THEN '22222222-0001-0001-0001-000000000002'::uuid  -- Halo Rings
      WHEN counter BETWEEN 26 AND 33 THEN '22222222-0001-0001-0001-000000000003'::uuid  -- Three-Stone Rings
      WHEN counter BETWEEN 34 AND 39 THEN '22222222-0001-0001-0001-000000000004'::uuid  -- Toi et Moi Rings
      WHEN counter BETWEEN 40 AND 47 THEN '22222222-0001-0001-0001-000000000005'::uuid  -- Eternity & Diamond Bands
      WHEN counter BETWEEN 48 AND 50 THEN '22222222-0001-0001-0001-000000000006'::uuid  -- Statement & Cocktail Rings
      ELSE '22222222-0001-0001-0001-000000000001'::uuid
    END;

    UPDATE public.products
    SET
      master_product_id  = pid,
      master_sku         = psku,
      category_id        = cat_id,
      subcategory_id     = sub_id,
      product_page_status = CASE WHEN is_active THEN 'published' ELSE 'draft' END
    WHERE id = rec.id;

    counter := counter + 1;
  END LOOP;
END $$;

