-- ── 6. FIX CATEGORY_ID / SUBCATEGORY_ID FOR EXISTING 50 PRODUCTS ─────────────
-- Ensure all 50 existing products have correct category_id and subcategory_id
-- based on their assigned master_product_id ranges

-- All DET-001 to DET-050 are Rings (already set in step 4, but ensure no NULLs)
UPDATE public.products
SET category_id = '11111111-0001-0001-0001-000000000001'
WHERE master_product_id LIKE 'DET-0%' AND category_id IS NULL;

-- Fix subcategory assignments for existing 50 products based on master_product_id
UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000001'
WHERE master_product_id IN ('DET-001','DET-002','DET-003','DET-004','DET-005','DET-006','DET-007','DET-008','DET-009','DET-010','DET-011','DET-012','DET-013','DET-014','DET-015');

UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000002'
WHERE master_product_id IN ('DET-016','DET-017','DET-018','DET-019','DET-020','DET-021','DET-022','DET-023','DET-024','DET-025');

UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000003'
WHERE master_product_id IN ('DET-026','DET-027','DET-028','DET-029','DET-030','DET-031','DET-032','DET-033');

UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000004'
WHERE master_product_id IN ('DET-034','DET-035','DET-036','DET-037','DET-038','DET-039');

UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000005'
WHERE master_product_id IN ('DET-040','DET-041','DET-042','DET-043','DET-044','DET-045','DET-046','DET-047');

UPDATE public.products SET subcategory_id = '22222222-0001-0001-0001-000000000006'
WHERE master_product_id IN ('DET-048','DET-049','DET-050');

-- ── 7. RLS POLICIES ──────────────────────────────────────────────────────────
-- Products: public read
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'products' AND policyname = 'products_public_read') THEN
    CREATE POLICY products_public_read ON public.products FOR SELECT TO anon, authenticated USING (is_active = true);
  END IF;
END $$;

-- Categories: public read
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'categories' AND policyname = 'categories_public_read') THEN
    CREATE POLICY categories_public_read ON public.categories FOR SELECT TO anon, authenticated USING (is_active = true);
  END IF;
END $$;
